/**
 * Settings (V17.2 UI): password-protected. Lock screen → tabs
 *   Security · Manual Schema Update · Schema Management · Secret Vault · Synchronization · AI/LLM Model · Danger Zone
 * Unlocking requires the Admin Password (default "admin" until changed). Settings re-lock after 5 minutes of inactivity.
 */
import { icon } from '../components/icons'; import { adminLibraryTab } from './adminLibrary'; import { adminPassphraseHtml, wireAdminPassphrase } from './schemaPassphraseAdmin'; import { adminMessagePanelHtml, wireAdminMessage } from './adminMessagePanel'; import { MIGRATION_DESCRIPTIONS } from '../../v17/services/migrations'; import { TIER_LABEL } from '../../v17/services/learningStore'; import { pingModel } from '../../v17/services/aiLlmService'; import { knowledgePathFor } from '../../v17/services/knowledgeSync'; import { renderTabs } from '../components/tabs'; import { openModal } from '../components/modal'; import { renderDataTable } from '../components/dataTable';
import { store } from '../state'; import { services, secrets, reloadSecrets, repository, aiConfig, setAiConfig, vaultProblem } from '../context'; import { e, options } from '../dom';
import { verifyPassword, changePassword, isUsingDefaultPassword, resetPasswordToDefault } from '../../services/passwordService';
import { legacyLeftovers, checkRegistry, serializeRegistry, describeIssue, validateSchemaModel } from '../../v17/sync/schemaFormat';
import { rejectionMessage, migrationMessage, type PullOutcome } from '../../v17/sync/syncService';
import { analyzeDependencies, rowsOf, diffRows } from '../../v17/engines/schemaRecordEngine';
